 tone(freq=440,duration=.1,type='triangle',volume=.04){if(!this.on||!this.ctx)return;const t=this.ctx.currentTime,o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type=type;o.frequency.setValueAtTime(freq,t);g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(volume,t+.008);g.gain.exponentialRampToValueAtTime(.0001,t+duration);o.connect(g).connect(this.ctx.destination);o.start(t);o.stop(t+duration+.02);},
 toggle(){this.init();this.on=!this.on;if(this.on){this.index=0;this.timer=setInterval(()=>this.music(),330);}else clearInterval(this.timer);$('soundBtn').innerHTML=this.on?'♫ <span>声音开</span>':'♫ <span>声音关</span>';$('soundBtn').setAttribute('aria-label',this.on?'关闭声音':'打开声音');},
 music(){if(document.hidden||!this.on)return;const notes=mode==='battle'?[220,293.66,329.63,440,415.3,329.63,293.66,246.94]:[196,293.66,329.63,392,440,392,329.63,293.66,220,329.63,392,440,493.88,440,392,329.63];this.tone(notes[this.index%notes.length],.32,'triangle',.018);if(this.index%4===0)this.tone(notes[this.index%notes.length]/2,.6,'sine',.025);this.index++;},
