function newState(){return {version:VERSION,chapter:0,unlocked:0,level:1,xp:0,gold:40,potions:5,ethers:3,limit:0,heroes:[{hp:0,mp:0},{hp:0,mp:0},{hp:0,mp:0}],progress:STORY.chapters.map(blankProgress),pos:{x:6,y:16},endings:[],playSeconds:0,started:Date.now(),updated:Date.now()};}
