function stats(i){let l=state.level,atk=[12,9,14][i]+l*3,def=[4,4,3][i]+l*1.25,hp=[91,78,86][i]+l*14,mp=[25,35,23][i]+l*3;state.progress.forEach((p,k)=>{if(p.relic){let r=STORY.chapters[k].relic;if(r.stat==='atk')atk+=r.value;if(r.stat==='def')def+=r.value;if(r.stat==='hp')hp+=r.value;if(r.stat==='mp')mp+=r.value;}});return {atk:Math.floor(atk),def:Math.floor(def),hp,mp};}
