function save(){if(!state)return false;state.updated=Date.now();try{localStorage.setItem(SAVE,JSON.stringify(state));$('saveStatus').textContent='● 进度已自动保存';$('saveNote').textContent='已存档 · 当前浏览器';lastSaved=performance.now();return true;}catch{ $('saveStatus').textContent='存档空间不可用';$('saveNote').textContent='自动存档不可用，请导出存档';return false;}}
function validateSave(s){
 if(!s||typeof s!=='object'||![1,VERSION].includes(s.version))throw Error('存档版本不兼容');
 const num=(n,a,b)=>Number.isFinite(n)&&n>=a&&n<=b;
 if(!Number.isInteger(s.chapter)||!num(s.chapter,0,7)||!Number.isInteger(s.unlocked)||!num(s.unlocked,s.chapter,7)||!Number.isInteger(s.level)||!num(s.level,1,30)||!num(s.xp,0,100000)||!num(s.gold,0,10000000)||!num(s.potions,0,999)||!num(s.ethers,0,999)||!num(s.limit,0,100))throw Error('存档数值无效');
 if(!Array.isArray(s.heroes)||s.heroes.length!==3||s.heroes.some(h=>!h||!num(h.hp,0,10000)||!num(h.mp,0,10000)))throw Error('伙伴数据无效');
 if(!Array.isArray(s.progress)||s.progress.length!==8)throw Error('章节数据不完整');
 for(let [chapterIndex,p] of s.progress.entries()){if(!p||['guide','witness','relic','side','boss','resolved'].some(k=>typeof p[k]!=='boolean')||!num(p.kills,0,9999)||![null,'a','b'].includes(p.choice)||!Array.isArray(p.cleared)||p.cleared.some(v=>!Number.isInteger(v)||v<0||v>3))throw Error('剧情数据无效');if(p.reflected===true&&(!Array.isArray(p.inquiryChoices)||p.inquiryChoices.length!==2||!Number.isInteger(p.inquiryChoices[0])||!Number.isInteger(p.inquiryChoices[1])||p.inquiryChoices[0]<0||p.inquiryChoices[0]>=AI_CASES[chapterIndex].first.options.length||p.inquiryChoices[1]<0||p.inquiryChoices[1]>=AI_CASES[chapterIndex].second.options.length))throw Error('追问记录无效');}
 if(!s.pos||!num(s.pos.x,0,MW-1)||!num(s.pos.y,0,MH-1)||!Array.isArray(s.endings)||s.endings.some(k=>!Object.hasOwn(STORY.endings,k))||!num(s.playSeconds,0,100000000))throw Error('存档结构无效');
 const clean=newState();for(let k of ['chapter','unlocked','level','xp','gold','potions','ethers','limit','playSeconds'])clean[k]=s[k];clean.heroes=s.heroes.map(h=>({hp:h.hp,mp:h.mp}));clean.progress=s.progress.map(p=>({reflected:p.reflected===true,inquiryChoices:Array.isArray(p.inquiryChoices)?p.inquiryChoices.filter(v=>Number.isInteger(v)&&v>=0&&v<3).slice(0,2):[],guide:p.guide,witness:p.witness,relic:p.relic,side:p.side,kills:p.kills,boss:p.boss,resolved:p.resolved,choice:p.choice,cleared:[...new Set(p.cleared)]}));clean.pos={x:s.pos.x,y:s.pos.y};clean.endings=[...new Set(s.endings)];return clean;
}
function loadStored(){try{let raw=localStorage.getItem(SAVE);return raw?validateSave(JSON.parse(raw)):null;}catch{return null;}}
function showTitle(){mode='title';$('titleScreen').hidden=false;$('playScreen').hidden=true;const saved=loadStored();$('continueBtn').hidden=!saved;if(saved){$('continueBtn').innerHTML='继续旅程 · 第 '+(saved.chapter+1)+' 章 <span>→</span>';$('titleChapter').textContent=STORY.chapters[saved.chapter].place;}}
