function enterMap(resetPos=true){map=createMap(state.chapter);if(resetPos)state.pos={...map.start};if(!walkable(Math.round(state.pos.x),Math.round(state.pos.y))||state.heroes.slice(0,partySize()).every(h=>h.hp<=0)){state.pos={...map.start};healParty();}path=[];mode='world';battle=null;fx=null;near=null;lastHint=null;$('interactHint').hidden=true;$('interactHint').textContent='';$('battleUI').hidden=true;$('fieldBar').hidden=false;$('touchControls').hidden=false;camera={x:0,y:0};location(ch().place);renderHUD();}
